session_start();
$dbFile=__DIR__.'/pharmacy.sqlite';
$db=new PDO('sqlite:'.$dbFile); $db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);
$db->exec("CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, name TEXT, username TEXT UNIQUE, password TEXT, role TEXT, active INTEGER DEFAULT 1);
