CREATE TABLE IF NOT EXISTS sales(id INTEGER PRIMARY KEY, product_id INTEGER, product_name TEXT, qty INTEGER, cost REAL, price REAL, total REAL, profit REAL, staff_id INTEGER, staff_name TEXT, sold_at TEXT);
