if(!$db->query('SELECT COUNT(*) FROM products')->fetchColumn()){$st=$db->prepare('INSERT INTO products(name,generic,category,batch,expiry,stock,reorder,cost,price,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)');$data=[['Napa 500mg','Paracetamol','Tablet','NAP-26','2027-05-31',85,20,0.80,1.50],['Seclo 20mg','Omeprazole','Capsule','SEC-25','2027-02-28',12,15,2.50,4.00],['DP 25mg','Diclofenac','Tablet','DP-11','2026-12-31',6,10,1.20,2.50],['Syrup Plus','Multivitamin','Syrup','SYP-01','2026-10-15',24,8,45,70]];foreach($data as $d){$d[] = date('Y-m-d');$st->execute($d);}}
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');} function money($v){return '৳'.number_format((float)$v,2);} function go($url='?'){header('Location: '.$url);exit;}
$action=$_POST['action']??$_GET['action']??'';
