if($action==='logout'){session_destroy();go();}
if(!isset($_SESSION['user'])): ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PharmaFlow Login</title><style><?php include __DIR__.'/style.css'; ?></style></head><body class="login"><div class="login-card"><div class="brand"><span class="brand-mark">✚</span><div><b>PharmaFlow</b><small>Pharmacy Operations Suite</small></div></div><h1>Welcome back</h1><p class="muted">Sign in to manage your pharmacy.</p><?php if(!empty($loginError)):?><div class="alert danger"><?=e($loginError)?></div><?php endif;?><form method="post"><input type="hidden" name="action" value="login"><label>Username<input name="username" required placeholder="admin"></label><label>Password<input type="password" name="password" required placeholder="••••••••"></label><button class="btn primary full">Sign in <span>→</span></button></form><div class="demo"><b>Demo access</b><br>Admin: <code>admin / admin123</code><br>Staff: <code>staff / staff123</code></div></div></body></html><?php exit; endif;
$user=$_SESSION['user'];$notice=$_SESSION['notice']??'';unset($_SESSION['notice']);
if($action==='toggle_user'&&$user['role']==='admin'){ $id=(int)$_POST['id'];$db->prepare("UPDATE users SET active=CASE active WHEN 1 THEN 0 ELSE 1 END WHERE id=? AND role='staff'")->execute([$id]);$_SESSION['notice']='Staff access status updated.';go('?page=staff');}
if($action==='add_user'&&$user['role']==='admin'){ $st=$db->prepare('INSERT INTO users(name,username,password,role) VALUES(?,?,?,?)');try{$st->execute([trim($_POST['name']),trim($_POST['username']),password_hash($_POST['password'],PASSWORD_DEFAULT),'staff']);$_SESSION['notice']='Staff account created successfully.';}catch(PDOException $e){$_SESSION['notice']='Username already exists. Choose another username.';}go('?page=staff');}
if($action==='delete_sale'){ $id=(int)$_POST['id'];$st=$db->prepare('SELECT * FROM sales WHERE id=?');$st->execute([$id]);$sale=$st->fetch(PDO::FETCH_ASSOC);if($sale&&($user['role']==='admin'||(int)$sale['staff_id']===(int)$user['id'])){$db->prepare('UPDATE products SET stock=stock+? WHERE id=?')->execute([$sale['qty'],$sale['product_id']]);$db->prepare('DELETE FROM sales WHERE id=?')->execute([$id]);$_SESSION['notice']='Sales record removed and stock restored.';}go('?page=sales');}
if($action==='delete_expense'&&$user['role']==='admin'){ $db->prepare('DELETE FROM expenses WHERE id=?')->execute([(int)$_POST['id']]);$_SESSION['notice']='Expense record removed.';go('?page=expenses');}
if($action==='add_product'){ $st=$db->prepare('INSERT INTO products(name,generic,category,batch,expiry,stock,reorder,cost,price,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)');$st->execute([trim($_POST['name']),trim($_POST['generic']),trim($_POST['category']),trim($_POST['batch']),$_POST['expiry'],(int)$_POST['stock'],(int)$_POST['reorder'],(float)$_POST['cost'],(float)$_POST['price'],date('Y-m-d')]);go('?page=inventory');}
if($action==='sale'){ $pid=(int)$_POST['product_id'];$qty=max(1,(int)$_POST['qty']);$p=$db->query("SELECT * FROM products WHERE id=$pid")->fetch(PDO::FETCH_ASSOC);if(!$p){$_SESSION['notice']='Medicine not found.';go('?page=sales');}if((int)$p['stock']<$qty){$_SESSION['notice']="Stock out: only {$p['stock']} units available for {$p['name']}.";go('?page=sales');}$total=$p['price']*$qty;$profit=($p['price']-$p['cost'])*$qty;$st=$db->prepare('INSERT INTO sales(product_id,product_name,qty,cost,price,total,profit,staff_id,staff_name,sold_at) VALUES(?,?,?,?,?,?,?,?,?,?)');$st->execute([$pid,$p['name'],$qty,$p['cost']*$qty,$p['price']*$qty,$total,$profit,$user['id'],$user['name'],date('Y-m-d H:i:s')]);$db->exec("UPDATE products SET stock=stock-$qty WHERE id=$pid");$_SESSION['notice']='Sale recorded successfully.';go('?page=sales');}
if($action==='expense'){ $st=$db->prepare('INSERT INTO expenses(title,amount,note,spent_at) VALUES(?,?,?,?)');$st->execute([trim($_POST['title']),(float)$_POST['amount'],trim($_POST['note']),$_POST['spent_at']?:date('Y-m-d')]);go('?page=expenses');}
if($action==='delete_product'&&$user['role']==='admin'){$db->exec('DELETE FROM products WHERE id='.(int)$_POST['id']);go('?page=inventory');}
$page=$_GET['page']??'dashboard';$lang=$_GET['lang']??($_SESSION['lang']??'en');$_SESSION['lang']=$lang;
$T=['en'=>['dashboard'=>'Dashboard','sales'=>'Sales','inventory'=>'Inventory','expenses'=>'Expenses','reports'=>'Reports','staff'=>'Staff','overview'=>'Business overview','today'=>'Today','revenue'=>'Revenue','profit'=>'Gross profit','orders'=>'Orders','low'=>'Low stock','quick'=>'Quick sale','recent'=>'Recent sales','add'=>'Add medicine','stock'=>'Stock','price'=>'Sale price','cost'=>'Unit cost','qty'=>'Qty','date'=>'Date','total'=>'Total','staff_name'=>'Staff','logout'=>'Sign out','search'=>'Search medicine...','export'=>'Export CSV','performance'=>'Performance comparison','period'=>'Period','current'=>'Current period','previous'=>'Previous period','expense'=>'Expenses','net'=>'Net profit','save'=>'Save','cancel'=>'Cancel','name'=>'Medicine name','generic'=>'Generic name','category'=>'Category','batch'=>'Batch no.','expiry'=>'Expiry date','reorder'=>'Reorder level','amount'=>'Amount','title'=>'Expense title','note'=>'Note'], 'bn'=>['dashboard'=>'ড্যাশবোর্ড','sales'=>'বিক্রয়','inventory'=>'ইনভেন্টরি','expenses'=>'খরচ','reports'=>'রিপোর্ট','staff'=>'স্টাফ','overview'=>'ব্যবসার সারাংশ','today'=>'আজ','revenue'=>'বিক্রয়','profit'=>'মোট লাভ','orders'=>'অর্ডার','low'=>'কম স্টক','quick'=>'দ্রুত বিক্রয়','recent'=>'সাম্প্রতিক বিক্রয়','add'=>'ওষুধ যোগ করুন','stock'=>'স্টক','price'=>'বিক্রয় মূল্য','cost'=>'ইউনিট খরচ','qty'=>'পরিমাণ','date'=>'তারিখ','total'=>'মোট','staff_name'=>'স্টাফ','logout'=>'লগ আউট','search'=>'ওষুধ খুঁজুন...','export'=>'CSV ডাউনলোড','performance'=>'পারফরম্যান্স তুলনা','period'=>'সময়কাল','current'=>'বর্তমান সময়','previous'=>'আগের সময়','expense'=>'খরচ','net'=>'নিট লাভ','save'=>'সংরক্ষণ','cancel'=>'বাতিল','name'=>'ওষুধের নাম','generic'=>'জেনেরিক নাম','category'=>'ক্যাটাগরি','batch'=>'ব্যাচ নম্বর','expiry'=>'মেয়াদ শেষ','reorder'=>'রিঅর্ডার লেভেল','amount'=>'পরিমাণ','title'=>'খরচের শিরোনাম','note'=>'নোট']];$L=$T[$lang];
$from=$_GET['from']??date('Y-m-d');$to=$_GET['to']??date('Y-m-d');$f=$db->quote($from);$t=$db->quote($to);
$metrics=$db->query("SELECT COALESCE(SUM(total),0) revenue,COALESCE(SUM(profit),0) profit,COUNT(*) orders FROM sales WHERE date(sold_at) BETWEEN $f AND $t")->fetch(PDO::FETCH_ASSOC);$expenses=(float)$db->query("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE spent_at BETWEEN $f AND $t")->fetchColumn();$metrics['net']=$metrics['profit']-$expenses;$low=$db->query('SELECT * FROM products WHERE stock<=reorder ORDER BY stock')->fetchAll(PDO::FETCH_ASSOC);$products=$db->query('SELECT * FROM products ORDER BY name')->fetchAll(PDO::FETCH_ASSOC);$recent=$db->query('SELECT * FROM sales ORDER BY id DESC LIMIT 8')->fetchAll(PDO::FETCH_ASSOC);
if($action==='export'){header('Content-Type:text/csv');header('Content-Disposition:attachment; filename=pharmacy-report.csv');$out=fopen('php://output','w');fputcsv($out,['Date','Medicine','Qty','Cost','Sales','Profit','Staff']);$q=$db->query("SELECT sold_at,product_name,qty,cost,total,profit,staff_name FROM sales WHERE date(sold_at) BETWEEN $f AND $t ORDER BY sold_at DESC");while($r=$q->fetch(PDO::FETCH_NUM))fputcsv($out,$r);exit;}
