edicine</th><th><?=$L['qty']?></th><th><?=$L['staff_name']?></th><th><?=$L['total']?></th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><b><?=e($r['product_name'])?></b><small><?=date('d M, H:i',strtotime($r['sold_at']))?></small></td><td><?=e($r['qty'])?></td><td><?=e($r['staff_name'])?></td><td><b><?=money($r['total'])?></b></td></tr><?php endforeach;?></tbody></table></div></div><div class="panel alert-panel"><div class="panel-head"><h2><?=$L['low']?></h2><span class="badge orange-bg"><?=count($low)?> items</span></div><?php foreach(array_slice($low,0,5) as $p):?><div class="stock-row"><span class="pill danger-pill">!</span><div><b><?=e($p['name'])?></b><small><?=e($p['generic'])?></small></div><strong class="red"><?=$p['stock']?> left</strong></div><?php endforeach;?></div></div></section>
