<?php elseif($page==='expenses'):?><div class="two-col"><div class="panel"><h2>Record daily expense</h2><form method="post" class="form-grid"><input type="hidden" name="action" value="expense"><label><?=$L['title']?><input name="title" required placeholder="Transport, electricity..."></label><label><?=$L['amount']?><input type="number" step="0.01" name="amount" required></label><label><?=$L['date']?><input type="date" name="spent_at" value="<?=date('Y-m-d')?>"></label><label><?=$L['note']?><textarea name="note" rows="3"></textarea></label><button class="btn primary full">+ <?=$L['save']?></button></form></div><div class="panel"><h2>Selected period</h2><div class="big-number red">− <?=money($expenses)?></div><p class="muted">Operating expenses reduce net profit.</p></div></div><div class="panel"><h2>Expense history</h2><div class="table-wrap"><table><thead><tr><th>Date</th><th>Title</th><th>Note</th><th>Amount</th><th></th></tr></thead><tbody><?php foreach($db->query('SELECT * FROM expenses ORDER BY id DESC LIMIT 20') as $r):?><tr><td><?=$r['spent_at']?></td><td><b><?=e($r['title'])?></b></td><td><?=e($r['note'])?></td><td class="red">− <?=money($r['amount'])?></td><td><?php if($user['role']==='admin'):?><form method="post" onsubmit="return confirm('Remove this expense?')"><input type="hidden" name="action" value="delete_expense"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="icon-btn">×</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>
<?php elseif($page==='staff'):?><?php if($user['role']==='admin'):?><div class="panel"><div class="panel-head"><h2>Staff access control</h2><span class="badge">Deactivate former staff</span></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Username</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($db->query("SELECT id,name,username,active FROM users WHERE role='staff' ORDER BY name") as $u):?><tr><td><b><?=e($u['name'])?></b></td><td><?=e($u['username'])?></td><td><span class="stock <?=($u['active']?'':'low')?>"><?=($u['active']?'Active':'Inactive')?></span></td><td><form method="post"><input type="hidden" name="action" value="toggle_user"><input type="hidden" name="id" value="<?=$u['id']?>"><button class="btn <?=($u['active']?'outline':'primary')?>"><?=($u['active']?'Deactivate':'Reactivate')?></button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php endif;?><?php if($user['role']==='admin'):?><div class="panel"><div class="panel-head"><h2>Add staff login</h2><span class="badge">Admin only</span></div><form method="post" class="form-grid"><input type="hidden" name="action" value="add_user"><label>Staff name<input name="name" required></label><label>Username<input name="username" required></label><label>Password<input type="password" name="password" minlength="6" required></label><button class="btn primary full">+ Create staff account</button></form></div><?php endif;?><div class="panel"><div class="panel-head"><h2>Staff performance</h2><span class="badge">Selected period</span></div><div class="table-wrap"><table><thead><tr><th>Staff member</th><th>Transactions</th><th>Sales revenue</th><th>Profit generated</th></tr></thead><tbody><?php $staffs=$db->query("SELECT staff_name,COUNT(*) orders,SUM(total) revenue,SUM(profit) profit FROM sales WHERE date(sold_at) BETWEEN $f AND $t GROUP BY staff_name ORDER BY revenue DESC");foreach($staffs as $s):?><tr><td><div class="staff-cell"><span><?=strtoupper(substr($s['staff_name'],0,1))?></span><b><?=e($s['staff_name'])?></b></div></td><td><?=$s['orders']?></td><td><b><?=money($s['revenue'])?></b></td><td class="green-text"><b><?=money($s['profit'])?></b></td></tr><?php endforeach;?></tbody></table></div></div><?php endif;?></div></main></div><div class="modal-bg" id="addModal"><div class="modal"><div class="panel-head"><h2><?=$L['add']?></h2><button class="icon-btn" onclick="modal('addModal')">×</button></div><form method="post" class="form-grid"><input type="hidden" name="action" value="add_product"><label><?=$L['name']?><input name="name" required></label><label><?=$L['generic']?><input name="generic"></label><label><?=$L['category']?><input name="category" placeholder="Tablet / Capsule"></label><label><?=$L['batch']?><input name="batch"></label><label><?=$L['expiry']?><input type="date" name="expiry"></label><label><?=$L['stock']?><input type="number" name="stock" value="0"></label><label><?=$L['reorder']?><input type="number" name="reorder" value="10"></label><label><?=$L['cost']?><input type="number" step="0.01" name="cost" required></label><label><?=$L['price']?><input type="number" step="0.01" name="price" required></label><div class="modal-actions"><button type="button" class="btn outline" onclick="modal('addModal')"><?=$L['cancel']?></button><button class="btn primary"><?=$L['save']?> medicine</button></div></form></div></div><script>function modal(id){document.getElementById(id).classList.toggle('show')}function filterRows(q){q=q.toLowerCase();document.querySelectorAll('#productTable tbody tr').forEach(r=>r.style.display=r.innerText.toLowerCase().includes(q)?'':'none')}</script></body></html>
